SELECT p.policy_id::TEXT AS row_id, p.title, p.type_cd, c.name AS type_cd_name, p.req_yn, p.sort_no, p.use_yn FROM policy p LEFT JOIN code c ON c.code_id = p.type_cd AND c.p_code_id = 'POLICY00' WHERE p.use_yn = 'Y' AND p.type_cd = #{typeCd}
AND p.title LIKE '%' || #{filterKeyword} || '%'
ORDER BY p.type_cd, p.sort_no LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM policy WHERE use_yn = 'Y'
AND type_cd = #{typeCd}
AND title LIKE '%' || #{filterKeyword} || '%'
